css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); display: grid; grid-template-columns: repeat(3, 1fr); gap: 5%; padding: 5%; border-radius: 12%; background: #0b1220; animation: quarter-turn calc(var(--loader-speed) * 3.6) cubic-bezier(.6, 0, .2, 1) infinite; }
.loader span { border-radius: 16%; background: var(--accent); animation: recolor calc(var(--loader-speed) * 1.8) steps(2, end) infinite; }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * .2); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * .4); }
.loader span:nth-child(4) { animation-delay: calc(var(--loader-speed) * .6); }
.loader span:nth-child(5) { animation-delay: calc(var(--loader-speed) * .8); }
.loader span:nth-child(6) { animation-delay: calc(var(--loader-speed) * 1); }
.loader span:nth-child(7) { animation-delay: calc(var(--loader-speed) * 1.2); }
.loader span:nth-child(8) { animation-delay: calc(var(--loader-speed) * 1.4); }
.loader span:nth-child(9) { animation-delay: calc(var(--loader-speed) * 1.6); }
@keyframes quarter-turn { 0%, 14% { transform: rotate(0deg); } 25%, 39% { transform: rotate(90deg); } 50%, 64% { transform: rotate(180deg); } 75%, 89% { transform: rotate(270deg); } 100% { transform: rotate(360deg); } }
@keyframes recolor { 0%, 100% { background: var(--accent); } 50% { background: var(--accent-2); } }
